**In-memory cache with TTL (Node.js/Express):**

```javascript
const NodeCache = require('node-cache');
const cache = new NodeCache({ stdTTL: 300 }); // 5 min TTL

app.get('/api/users/:id', (req, res) => {
  const cached = cache.get(`user:${req.params.id}`);
  if (cached) return res.json(cached);

  fetchUserFromDB(req.params.id).then(user => {
    cache.set(`user:${req.params.id}`, user);
    res.json(user);
  });
});

app.put('/api/users/:id', (req, res) => {
  updateUserInDB(req.params.id, req.body).then(user => {
    cache.del(`user:${req.params.id}`); // Invalidate
    res.json(user);
  });
});
```

**Redis (distributed):**

```javascript
const redis = require('redis');
const client = redis.createClient();

app.get('/api/users/:id', async (req, res) => {
  const cached = await client.get(`user:${req.params.id}`);
  if (cached) return res.json(JSON.parse(cached));

  const user = await fetchUserFromDB(req.params.id);
  await client.setEx(`user:${req.params.id}`, 300, JSON.stringify(user));
  res.json(user);
});
```

In-memory fast for single-instance; Redis for multi-instance deployments. Invalidate on writes. Add error handling on cache miss if DB goes down.
